-- ═══════════════════════════════════════════════════════════════════
--  Dormetria · 8 semanas de diario para seis pacientes DEMO
--  Generado el 16/10/2026 · período 21/08/2026 al 15/10/2026
--
--  QUÉ HACE
--  Carga 56 noches a cada uno de: Marie Curie, Juana de Arco, Elena,
--  Frida Kahlo, Peter Pan y Tomás Ferrante.
--
--  SE PUEDE CORRER LAS VECES QUE QUIERAS. Borra primero las noches de
--  ESE período y de ESOS seis, y las vuelve a insertar. No toca a nadie
--  más, ni ninguna noche fuera del 21/08 al 15/10.
--
--  CADA PERFIL SE VERIFICÓ CONTRA EL MOTOR de la app antes de generarlo.
--  Lo que el motor dice de cada uno:
--
--    Curie     "insomnio mixto"             lat 44m · WASO 61m · efic 75%
--    Juana     "insomnio de conciliación"   lat 92m · jet lag 129m
--    Elena     "dentro de límites normales" efic 95%   <- el control
--    Kahlo     "insomnio mixto"             WASO 57m · siestas 36%
--    Peter     "dentro de límites normales" jet lag 192m · SD mid 104m
--              duerme BIEN pero a destiempo: se le enciende la etiqueta
--              de cronodisrupción y la conducta dice que NO hay
--              indicación de tratar insomnio. Es el caso que muestra
--              que la app no sobrediagnostica.
--    Ferrante  "insomnio de mantenimiento"  WASO 96m · efic 69%
--
--  Si alguno no existe con ese código o ese nombre, no se le inserta
--  nada. La consulta del final dice a quién encontró.
-- ═══════════════════════════════════════════════════════════════════

-- ── 0 · Códigos para los dos que no lo tenían ──────────────────────
--
-- La app siembra los pacientes de ejemplo BUSCÁNDOLOS POR CÓDIGO
-- (DM_CODIGOS_DEMO en index.html). Elena y Tomás Ferrante no tenían, así
-- que no se le vinculaban a nadie por más que existieran en la base.
--
-- Si alguno de los dos no existe, el update no hace nada y la consulta
-- del final lo va a mostrar con 0 noches.

update public.patients set code = 'ELENA1'
 where lower(name) = 'elena' and code is distinct from 'ELENA1';

update public.patients set code = 'TOMAS1'
 where lower(lname) like '%ferrante%' and code is distinct from 'TOMAS1';

-- Y que los seis queden marcados como ejemplo también en la base, no
-- sólo por el dominio del correo. `is_demo` es lo que mira dmEsDemo
-- primero, y es más confiable que adivinar por el mail.
update public.patients set is_demo = true
 where code in ('CURIE1','JUANA1','KAHLO1','PETER1','ELENA1','TOMAS1');

begin;

with gente as (
  select 'curie'::text as k, email from public.patients where code = 'CURIE1' limit 1
  union all select 'juana'::text as k, email from public.patients where code = 'JUANA1' limit 1
  union all select 'kahlo'::text as k, email from public.patients where code = 'KAHLO1' limit 1
  union all select 'peter'::text as k, email from public.patients where code = 'PETER1' limit 1
  union all select 'elena'::text as k, email from public.patients where code = 'ELENA1' limit 1
  union all select 'ferrante'::text as k, email from public.patients where code = 'TOMAS1' limit 1
)
delete from public.sleep_diary s
 using gente g
 where s.patient_email = g.email
   and s.diary_date between date '2026-08-21' and date '2026-10-15';

