insert into public.sleep_diary (patient_email, diary_date, bedtime, wake_time, get_up_time, sleep_minutes, sleep_latency_mins, awakenings, wake_in_bed_mins, awake_in_bed_after_mins, nap_minutes, sleep_quality, mood, energy, day_type, coffee_cups, alcohol_drinks, screen_minutes, exercise_mins, medications, schema_version)
select g.email, d.diary_date::date, d.bedtime::time, d.wake_time::time,
       d.get_up_time::time, d.sleep_minutes, d.sleep_latency_mins, d.awakenings,
       d.wake_in_bed_mins, d.awake_in_bed_after_mins, d.nap_minutes,
       d.sleep_quality, d.mood, d.energy, d.day_type, d.coffee_cups,
       d.alcohol_drinks, d.screen_minutes, d.exercise_mins, d.medications,
       d.schema_version
  from d join gente g on g.k = d.k;

commit;

-- ── Control: a quién encontró y cuántas noches le quedaron ──────────
with gente as (
  select 'curie'::text as k, email from public.patients where code = 'CURIE1' limit 1
  union all select 'juana'::text as k, email from public.patients where code = 'JUANA1' limit 1
  union all select 'kahlo'::text as k, email from public.patients where code = 'KAHLO1' limit 1
  union all select 'peter'::text as k, email from public.patients where code = 'PETER1' limit 1
  union all select 'elena'::text as k, email from public.patients where code = 'ELENA1' limit 1
  union all select 'ferrante'::text as k, email from public.patients where code = 'TOMAS1' limit 1
)
select g.k as perfil, g.email,
       count(s.*) as noches,
       min(s.diary_date) as desde, max(s.diary_date) as hasta
  from gente g
  left join public.sleep_diary s
    on s.patient_email = g.email
   and s.diary_date between date '2026-08-21' and date '2026-10-15'
 group by g.k, g.email
 order by g.k;
